//! include/hypertabular.h, the C header, is generated by cbindgen (configured in cbindgen.toml)
//! from src/kernel/exports.rs and the types its exports take, and the Swift artifact bundle
//! carries a byte-identical copy as its module's header. This regenerates it and fails when
//! either committed file differs, so a change to an export, a type it takes or a doc comment on
//! either cannot leave a header behind. `HYPERTABULAR_BLESS=1` writes both.
//!
//! Every export is declared through the `export!` macro, and cbindgen reads source without
//! expanding macros (expansion is a nightly rustc flag). So this test hands it exports.rs as
//! the macro writes each function under the `exports` feature: the `export! { … }` around each
//! one dropped, and `#[unsafe(no_mangle)] pub unsafe extern "C"` before its `fn`, the
//! macro's own expansion, which the test first checks is still what the macro says. The
//! source files cbindgen reads are named one by one: those three in src/kernel, and the two
//! of HyperCast's (found through `cargo metadata`) that define what a column declares and
//! what its buffer holds. The canary export, which only check-core.sh compiles in, is left out
//! by cbindgen.toml.
//!
//! Two places cannot check it, and every other leg does. wasm: `cargo metadata` is a
//! subprocess wasmtime cannot start, so the test is compiled out. A copy of rust/ without the
//! repository around it (the Forge's musl build takes only rust/ and corpus/ into its
//! container): the test says so and passes. Line endings are LF on every checkout, Windows'
//! included (.gitattributes), so the comparison is byte for byte.
#![cfg(not(target_family = "wasm"))]

use cbindgen::ir::{ItemContainer, Literal};
use std::path::{Path, PathBuf};
use std::process::Command;

const HEADERS: [&str; 2] = [
    "../include/hypertabular.h",
    "../swift/HyperTabularCore.artifactbundle/include/hypertabular.h",
];

/// What `export!` puts before each function's `fn`; the test puts the expansion there instead.
const EXPANSION: [&str; 2] = [
    "#[cfg_attr(feature = \"exports\", unsafe(no_mangle))]",
    "pub unsafe extern \"C\" fn $name(",
];

/// exports.rs with every `export!` invocation written out as the macro expands it, and how
/// many there are.
fn expanded(source: &str) -> (String, usize) {
    for line in EXPANSION {
        assert!(
            source.contains(line),
            "export! no longer expands to `{line}`; tests/header.rs writes its exports out \
             that way and has to follow the macro"
        );
    }
    let mut out = String::with_capacity(source.len());
    let mut inside = false;
    let mut count = 0;
    for line in source.lines() {
        if line == "export! {" {
            assert!(!inside, "an export! inside another");
            inside = true;
            continue;
        }
        if inside && line == "}" {
            inside = false;
            continue;
        }
        if inside && let Some(rest) = line.strip_prefix("    fn ") {
            out.push_str("    #[unsafe(no_mangle)]\n    pub unsafe extern \"C\" fn ");
            out.push_str(rest);
            count += 1;
        } else {
            out.push_str(line);
        }
        out.push('\n');
    }
    assert!(
        !inside,
        "an export! that does not close at the start of a line"
    );
    (out, count)
}

/// The source directory of the HyperCast this build resolved: the registry's, or a patch's.
fn hypercast_src(crate_dir: &Path) -> PathBuf {
    let cargo = std::env::var_os("CARGO").unwrap_or_else(|| "cargo".into());
    let output = Command::new(cargo)
        .args(["metadata", "--format-version", "1", "--manifest-path"])
        .arg(crate_dir.join("Cargo.toml"))
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "cargo metadata: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let metadata: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let manifest = metadata["packages"]
        .as_array()
        .unwrap()
        .iter()
        .find(|package| package["name"] == "hypercast")
        .expect("hypercast is not in cargo metadata")["manifest_path"]
        .as_str()
        .unwrap()
        .to_owned();
    Path::new(&manifest).parent().unwrap().join("src")
}

#[test]
fn committed_headers_are_what_cbindgen_generates() {
    let crate_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let bless = std::env::var_os("HYPERTABULAR_BLESS").is_some();
    if !bless && !crate_dir.join("../include").is_dir() {
        eprintln!("skipped: no include/ beside rust/, so this is not a whole checkout");
        return;
    }
    let kernel = crate_dir.join("src/kernel");
    let (exports, count) = expanded(&std::fs::read_to_string(kernel.join("exports.rs")).unwrap());
    let scratch = Path::new(env!("CARGO_TARGET_TMPDIR")).join("header");
    std::fs::create_dir_all(&scratch).unwrap();
    std::fs::write(scratch.join("exports.rs"), exports).unwrap();
    let hypercast = hypercast_src(crate_dir);

    let config = cbindgen::Config::from_file(crate_dir.join("cbindgen.toml")).unwrap();
    let mut bindings = cbindgen::Builder::new()
        .with_config(config)
        .with_src(scratch.join("exports.rs"))
        .with_src(kernel.join("abi.rs"))
        .with_src(kernel.join("delimited/fill.rs"))
        .with_src(hypercast.join("abi.rs"))
        .with_src(hypercast.join("verdict.rs"))
        .generate()
        .unwrap();
    // An associated constant whose value is a struct (`CellVerdict::OK`, `RawNumFormat::ZERO`)
    // has no C spelling: cbindgen would write a compound literal naming constants it never
    // emits. No configuration leaves them out (`[export] exclude` does not reach associated
    // constants), hence the IR, behind cbindgen's `unstable_ir` feature, as HyperCast's own
    // header test does. A transparent struct's constant is its one field's value
    // (`NativeDigits_NONE`), and the integer constants stay: the flags, the failure codes and
    // the layouts' sizes are what a C caller reads and builds with.
    for item in &mut bindings.items {
        if let ItemContainer::Struct(item) = item
            && !item.is_transparent
        {
            item.associated_constants
                .retain(|constant| !matches!(constant.value, Literal::Struct { .. }));
        }
    }
    let mut generated = Vec::new();
    bindings.write(&mut generated);

    // Every export and nothing else: a prototype for each export! in exports.rs but the
    // canary.
    let text = String::from_utf8(generated.clone()).unwrap();
    let prototypes = text
        .lines()
        .filter(|line| line.contains(" hypertabular_") && line.ends_with(");"))
        .count();
    assert!(
        !text.contains("hypertabular_canary"),
        "the canary reached the header"
    );
    assert_eq!(
        prototypes,
        count - 1,
        "prototypes in the header, against exports.rs' export!s"
    );

    for header in HEADERS.map(|path| crate_dir.join(path)) {
        if bless {
            std::fs::write(&header, &generated).unwrap();
            continue;
        }
        let committed = std::fs::read(&header).unwrap_or_default();
        assert!(
            committed == generated,
            "{} is not what cbindgen generates from src/; \
             run `HYPERTABULAR_BLESS=1 cargo test --test header` in rust/",
            header.display()
        );
    }
}
